const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const beijing = ee.Geometry.Rectangle([115.8, 39.6, 117.5, 41.1], null, false);
    const shanghai = ee.Geometry.Rectangle([121.0, 30.7, 121.9, 31.6], null, false);

    const start2013 = '2013-08-05';
    const end2013 = '2013-08-13'; // end is exclusive
    const doyStart = 217;
    const doyEnd = 224;

    const scale = 1000;
    const maxPixels = 1e9;

    // Helper: evaluate a server object
    const evalAsync = (obj) =>
      new Promise((resolve, reject) => obj.evaluate((v, e) => (e ? reject(e) : resolve(v))));

    // Total pixel counts (sampling grid) per AOI
    async function getTotalPixels(aoi) {
      const total = ee.Image(1)
        .rename('const')
        .reduceRegion({ reducer: ee.Reducer.count(), geometry: aoi, scale: scale, maxPixels: maxPixels })
        .get('const');
      return await evalAsync(total);
    }

    const totalPxBJ = await getTotalPixels(beijing);
    const totalPxSH = await getTotalPixels(shanghai);
    if (!totalPxBJ || !totalPxSH) {
      console.log('Total pixel count calculation failed.');
      console.log('C3');
      return;
    }

    // Masking for MOD11A2/MYD11A2 Daytime LST
    function maskMOD11A2(img) {
      const qc = img.select('QC_Day');
      const qa = qc.bitwiseAnd(3); // bits 0-1
      const mask = qa.lte(1); // good or other quality
      const lstC = img.select('LST_Day_1km').updateMask(mask).multiply(0.02).subtract(273.15).rename('LST');
      return lstC.copyProperties(img, img.propertyNames());
    }

    function getCol(product, start, end) {
      return ee.ImageCollection(product).filterDate(start, end).map(maskMOD11A2);
    }

    function getBaselineCol(product) {
      return ee.ImageCollection(product)
        .filter(ee.Filter.calendarRange(2000, 2012, 'year'))
        .filter(ee.Filter.calendarRange(doyStart, doyEnd, 'day_of_year'))
        .map(maskMOD11A2);
    }

    async function pick2013Collection(aoi) {
      let usedProduct = null;
      let usedStart = start2013;
      let usedEnd = end2013;

      let col = getCol('MODIS/061/MOD11A2', usedStart, usedEnd);
      let size = await evalAsync(col.size());
      if (size === 0) {
        col = getCol('MODIS/061/MYD11A2', usedStart, usedEnd);
        size = await evalAsync(col.size());
        if (size === 0) {
          // widen by ±1 day
          usedStart = '2013-08-04';
          usedEnd = '2013-08-14';
          col = getCol('MODIS/061/MOD11A2', usedStart, usedEnd);
          size = await evalAsync(col.size());
          if (size === 0) {
            col = getCol('MODIS/061/MYD11A2', usedStart, usedEnd);
            size = await evalAsync(col.size());
            if (size === 0) {
              return { col: null, usedProduct: null, usedStart, usedEnd, size: 0 };
            } else {
              usedProduct = 'MYD11A2';
            }
          } else {
            usedProduct = 'MOD11A2';
          }
        } else {
          usedProduct = 'MYD11A2';
        }
      } else {
        usedProduct = 'MOD11A2';
      }
      return { col, usedProduct, usedStart, usedEnd, size };
    }

    async function pickBaselineCollection() {
      // Try Terra first; fallback to Aqua if Terra empty
      let col = getBaselineCol('MODIS/061/MOD11A2');
      let size = await evalAsync(col.size());
      let usedProduct = 'MOD11A2';
      if (size === 0) {
        col = getBaselineCol('MODIS/061/MYD11A2');
        size = await evalAsync(col.size());
        if (size === 0) {
          return { col: null, usedProduct: null, size: 0 };
        } else {
          usedProduct = 'MYD11A2';
        }
      }
      return { col, usedProduct, size };
    }

    async function computeCollectionStats(col, aoi, totalPx) {
      const fc = ee.FeatureCollection(
        col.map(function (img) {
          const mean = img.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: aoi,
            scale: scale,
            maxPixels: maxPixels
          }).get('LST');
          const count = img.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: aoi,
            scale: scale,
            maxPixels: maxPixels
          }).get('LST');
          return ee.Feature(null, { meanC: mean, count: count });
        })
      );
      const nImages = await evalAsync(col.size());
      const validFc = fc.filter(ee.Filter.gt('count', 0));
      const nValid = await evalAsync(validFc.size());
      let meanOfMeans = null;
      let avgCount = null;
      if (nValid > 0) {
        meanOfMeans = await evalAsync(validFc.aggregate_mean('meanC'));
        avgCount = await evalAsync(validFc.aggregate_mean('count'));
      }
      const avgValidPct = avgCount && totalPx ? (avgCount / totalPx) * 100.0 : 0;
      return { nImages, nValid, meanOfMeans, avgCount, avgValidPct };
    }

    // 2. Data Acquisition & Check
    const baselinePick = await pickBaselineCollection();
    if (!baselinePick.col) {
      console.log('Baseline images: 0');
      console.log('C1');
      return;
    }

    const pick2013BJ = await pick2013Collection(beijing);
    const pick2013SH = await pick2013Collection(shanghai);
    if (!pick2013BJ.col || !pick2013SH.col) {
      console.log(`2013 images Beijing: ${pick2013BJ.size || 0}, Shanghai: ${pick2013SH.size || 0}`);
      console.log('C1');
      return;
    }

    // 3. Processing and pixel count checks
    const stats2013BJ = await computeCollectionStats(pick2013BJ.col, beijing, totalPxBJ);
    const stats2013SH = await computeCollectionStats(pick2013SH.col, shanghai, totalPxSH);
    const statsBaseBJ = await computeCollectionStats(baselinePick.col, beijing, totalPxBJ);
    const statsBaseSH = await computeCollectionStats(baselinePick.col, shanghai, totalPxSH);

    if (stats2013BJ.nValid === 0 || stats2013SH.nValid === 0 || statsBaseBJ.nValid === 0 || statsBaseSH.nValid === 0) {
      console.log('No valid pixels after masking in one or more periods/locations.');
      console.log('C2');
      return;
    }

    // 4. Calculation
    const mean2013BJ = stats2013BJ.meanOfMeans;
    const mean2013SH = stats2013SH.meanOfMeans;
    const meanBaseBJ = statsBaseBJ.meanOfMeans;
    const meanBaseSH = statsBaseSH.meanOfMeans;

    if (
      mean2013BJ === null || mean2013SH === null || meanBaseBJ === null || meanBaseSH === null ||
      !isFinite(mean2013BJ) || !isFinite(mean2013SH) || !isFinite(meanBaseBJ) || !isFinite(meanBaseSH)
    ) {
      console.log('Computation produced null/NaN.');
      console.log('C3');
      return;
    }

    const anomBJ = mean2013BJ - meanBaseBJ;
    const anomSH = mean2013SH - meanBaseSH;
    const diff = anomSH - anomBJ;

    // 5. Output concise evidence (<=20 lines)
    console.log(`2013 Product BJ: ${pick2013BJ.usedProduct}, SH: ${pick2013SH.usedProduct}; Baseline: ${baselinePick.usedProduct}`);
    console.log(`Beijing 2013 imgs: ${stats2013BJ.nImages}, valid%: ${stats2013BJ.avgValidPct.toFixed(1)} (px≈${Math.round(stats2013BJ.avgCount || 0)}/${totalPxBJ})`);
    console.log(`Beijing base imgs: ${statsBaseBJ.nImages}, valid%: ${statsBaseBJ.avgValidPct.toFixed(1)} (avg px≈${Math.round(statsBaseBJ.avgCount || 0)}/${totalPxBJ})`);
    console.log(`Beijing mean LST: 2013=${mean2013BJ.toFixed(2)}°C, base=${meanBaseBJ.toFixed(2)}°C, anomaly=${anomBJ.toFixed(2)}°C`);
    console.log(`Shanghai 2013 imgs: ${stats2013SH.nImages}, valid%: ${stats2013SH.avgValidPct.toFixed(1)} (px≈${Math.round(stats2013SH.avgCount || 0)}/${totalPxSH})`);
    console.log(`Shanghai base imgs: ${statsBaseSH.nImages}, valid%: ${statsBaseSH.avgValidPct.toFixed(1)} (avg px≈${Math.round(statsBaseSH.avgCount || 0)}/${totalPxSH})`);
    console.log(`Shanghai mean LST: 2013=${mean2013SH.toFixed(2)}°C, base=${meanBaseSH.toFixed(2)}°C, anomaly=${anomSH.toFixed(2)}°C`);
    console.log(`ΔAnomaly (SH - BJ): ${diff.toFixed(2)}°C`);

    // 6. Final Answer
    if (!isFinite(anomBJ) || !isFinite(anomSH)) {
      console.log('C3');
    } else if (anomSH > anomBJ) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
